import sys
import time
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    """Return x if it is even; raise Bad(x) if it is odd."""
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element in a thread pool and return the results in input order.

    If any element is odd, raise Bad for the odd element with the lowest index,
    regardless of which worker thread finishes first. Return [] for empty input.
    """
    with ThreadPoolExecutor() as pool:
        futures = [pool.submit(check, x) for x in xs]
        try:
            return [f.result() for f in futures]
        except Bad:
            for f in futures:
                f.cancel()
            raise


def test_all_even_returns_values_when_all_even() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_raises_bad_for_odd() -> None:
    with pytest.raises(Bad) as exc:
        all_even([2, 3, 4])
    assert exc.value.n == 3


def test_all_even_reports_lowest_index_bad_not_first_finished(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def slow_check(x: int) -> int:
        if x == 3:
            time.sleep(0.2)
            raise Bad(x)
        if x % 2 == 1:
            raise Bad(x)
        return x

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    with pytest.raises(Bad) as exc:
        all_even([2, 3, 5])
    assert exc.value.n == 3
